flow:
appId: com.complior.mobile
name: start-ekran
---
# Production путь допуска (118): запуск → First-Run → demo-вход F03 →
# Erstinformation → continue при current gate → Start (start_tabs и КАЖДАЯ
# вкладка своим testID). Кадры Start — после перехода и assertVisible СВОЕГО
# селектора (testID в mobile/src/features/start/**): idle → composer →
# decision → resume. Прямой /start без допуска экраном не проверяется —
# маршрут и пробы допуска остаются 118.
- launchApp
- assertVisible: {id: first-run-continue}
- tapOn: {id: first-run-continue}
- assertVisible: {id: auth-demo-entry}
- tapOn: {id: auth-demo-entry}
- assertVisible: {id: erstinfo_gate_current}
- tapOn: {id: erstinfo_continue_start}
- assertVisible: {id: start_tabs}
- assertVisible: {id: start_tab_start}
- assertVisible: {id: start_tab_vorgaenge}
- assertVisible: {id: start_tab_schutz}
- assertVisible: {id: start_tab_post}
- assertVisible: {id: start_sostojanie_idle}
- takeScreenshot: start-ekran-f04-01
- tapOn: {id: start_next_variant}
- assertVisible: {id: start_sostojanie_composer}
- takeScreenshot: start-ekran-f04-07
- tapOn: {id: start_next_variant}
- assertVisible: {id: start_sostojanie_decision}
- takeScreenshot: start-ekran-f04-08
- tapOn: {id: start_next_variant}
- assertVisible: {id: start_sostojanie_resume}
- takeScreenshot: start-ekran-f04-13

testids_tekst:
// Stand-in кода экрана батареи 138: каждый селектор флоя start-ekran обязан
// иметь носитель testID в коде экрана; свои селекторы — mobile/src/features/
// start, селекторы пути допуска — соседние экраны (onboarding 118, auth
// 135). В модели дерева носители — эти файлы (продукт несёт те же testID).
// Селекторы Start (внутри зоны 138), честный TSX:
<View testID="start_sostojanie_idle" />
<View testID="start_sostojanie_composer" />
<View testID="start_sostojanie_decision" />
<View testID="start_sostojanie_resume" />
<View testID="start_next_variant" />

testids_onboarding:
// Stand-in источников ПУТИ допуска (не зона 138): First-Run/Erstinformation —
// 118/135; demo-вход — 135 (auth). Продукт несёт эти testID в своих экранах.
<View testID="first-run-continue" />
<View testID="erstinfo_gate_current" />
<View testID="erstinfo_continue_start" />

app_start_tekst:
// Состав Start наблюдаем ПО ВКЛАДКЕ, не только узлом контейнера вкладок
// (118: пустой контейнер без вкладок — не Start). TabShell — зона 108/995,
// 138 читает состав, не правит.
<View testID="start_tabs" />
<View testID="start_tab_start" />
<View testID="start_tab_vorgaenge" />
<View testID="start_tab_schutz" />
<View testID="start_tab_post" />
